-- Seed di periodi e giorni della Bacheca, importati da web/public/content/bacheca-layout.json
-- (fonte strutturale reale della route /bacheca, per decisione già presa nell'inventario).
-- Rinominato il tipo di blocco 'external' in 'link' (stesso significato, nome più chiaro)
-- e rimosso 'devId' (serviva solo come riferimento incrociato nella vecchia modalità
-- 'sviluppo' del JSON grezzo, superata ora che l'editor permette di modificare in loco).

INSERT INTO bacheca_periods (id, title, position, created_by, created_at, updated_at)
SELECT 'settembre', 'Settembre', 0, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 1, 'settembre', 'il-primo-giorno', 'Il primo giorno', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"text","text":"Se ti va puoi ascoltare la canzone mentre guardi e leggi"}]},{"width":0.5,"blocks":[{"type":"audio","key":"bacheca/settembre/giorno-1/audio/oslo.mp3","label":"Oslo (Skioffi)"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-1/original/01.jpg","thumbKey":"bacheca/settembre/giorno-1/thumb/01.jpg","caption":"Non puoi capire come mi sentivo emozionato a essere finalmente davanti quel portone che avevo visto solo su maps"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-1/original/02.jpg","thumbKey":"bacheca/settembre/giorno-1/thumb/02.jpg","caption":"Qui ancora non sapevo nemmeno quale fosse di preciso il tuo balcone. Ma una cosa divertente è che non volevo stare troppo sotto perché non volevo che mi vedessi ahaha spero che ci vedessimo nello stesso momento sotto"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-1/original/03.jpg","thumbKey":"bacheca/settembre/giorno-1/thumb/03.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-1/original/04.jpg","thumbKey":"bacheca/settembre/giorno-1/thumb/04.jpg","caption":"Inutile dire come mi batteva il cuore quando mi hai mandato questa foto. Sono rimasto a fissare il numero dell’ascensore e poi appena è diventato 1 sono scappato via ahaha. Quando sei uscita sembravi un sogno"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-1/original/05.jpg","thumbKey":"bacheca/settembre/giorno-1/thumb/05.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-1/original/06.jpg","thumbKey":"bacheca/settembre/giorno-1/thumb/06.jpg","caption":"Purtroppo questo gattino è l’unica cosa che racconta quella sera, ma quella sera c’è stato anche il nostro primo appuntamento, i polpi, il cameriere, i regali, la letterina, la piazza ancora con l’imbarazzo senza sapere che dire. Non ricordo nemmeno com’eri vestita ahaha, ricordo la gonna nera di jeans tipo. Però eri stupenda, questo lo ricordo. E che avevi il lucidalabbra"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Abbiamo pochissime foto di quel giorno 🥲"}]}]}]}', 0, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 2, 'settembre', 'il-secondo-giorno', 'Il secondo giorno', '{"rows":[{"columns":[{"width":0.49999999999999994,"blocks":[{"type":"text","text":"Credo che questa sia letteralmente l’unica foto del nostro secondo giorno, a meno che non mi sto confondendo. È una ed è semplice, però alla fine questa foto quanti ricordi racchiude? Il mc, la musica in macchina, le chiacchierate, tu che ti lamentavi perché non mi sbrigavo a cambiare canzone ahaha. Mi ricordo che quel giorno comunque abbiamo riso tanto. È stato bello scegliere la canzone del tuo compleanno insieme. Che poi se ti ricordi, abbiamo scelto pure la torta insieme, e in qualche modo avevamo parlato insieme pure del vestito mesi prima ahaha. Comunque ricordo che avevo voglia di prenderti e ballare con qualche canzone quel lento, e te l’ho anche chiesto, però ho fatto finta che stessi scherzando ahaha mi imbarazzava, ma allo stesso tempo avevo voglia di farlo. Eri molto bella con il sole tutto il tempo in faccia, ti illuminava gli occhi come nelle foto che mi mandavi ogni tanto. Non mi ricordo poi che abbiamo fatto per tutto il resto della giornata, credo che quella sera siamo andati mangiare quella pizza e abbiamo parlato. So che siamo stati anche a casa, ma non so se è stato prima o dopo la pizza"}]},{"width":0.49999999999999994,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-2/original/01.jpg","thumbKey":"bacheca/settembre/giorno-2/thumb/01.jpg"}]}]}]}', 1, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 3, 'settembre', 'il-terzo-giorno', 'Il terzo giorno', '{"rows":[{"columns":[{"width":0.49999999999999994,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/01.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/01.jpg","caption":"Non ha senso che mi metta a commentare ogni foto, però posso solo dire un po’ per tutte che comunque eravamo bellissimi"}]},{"width":0.49999999999999994,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/02.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/02.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/03.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/03.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/04.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/04.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/05.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/05.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/06.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/06.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/07.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/07.jpg","caption":"Vorrei abbracciarti così"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/08.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/08.jpg","caption":"Guarda quanto erano grandi i tuoi occhi in quel momento ahaha"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/09.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/09.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/10.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/10.jpg"},{"type":"text","text":"Come vorrei dormire sempre e per sempre ahaha"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/11.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/11.jpg"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/12.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/12.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/13.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/13.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/14.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/14.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/15.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/15.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/16.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/16.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/17.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/17.jpg","caption":"Hey.Comunque eri carina quando ti nascondevi, mi ricordo che pure quello è stato un bel momento divertente"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/18.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/18.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/19.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/19.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/20.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/20.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/21.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/21.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/22.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/22.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/23.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/23.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"text","text":"Questa è più adatta qui che sei una principessa ahaha"}]},{"width":0.5,"blocks":[{"type":"audio","key":"bacheca/settembre/giorno-3/audio/perfect.mp3","label":"Perfect (Ed Sheeran)"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/24.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/24.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/25.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/25.jpg","caption":"Qui sembrava quasi che mi stessi guardando ahaha"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/26.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/26.jpg"}]}]},{"columns":[{"width":0.5000000000000001,"blocks":[{"type":"text","text":"Beh che dire di queste 4 foto? Te le ho fatte a sgamo, sperando che nessuno mi vedesse e facendomi forte del fatto che tutte le tue amiche te le stessero facendo. Allora ho pensato che forse mi potevo “mimetizzare” ahaha e fartene qualcuna pure io. Poi si vabbé mi sono imbarazzato e ho pensato che forse qualcuno potesse pensare male e mi sono fermato. Mi ricordo che quella sera eri perfetta, avrei voluto farti foto tutto il tempo. Però amo questa foto qui accanto. Ne ho fatte solo 4, ma puoi dire quello che vuoi, che non ti piace, che fa schifo, non lo so. Ma per me vederti sorridere in quel modo non ha prezzo. Eri bella. Con la tua coroncina e la tua fascia “birthday queen” ahaha e quel vestito rosso che hai aspettato così tanto per mettere e che sono felice di averti visto addosso. Quando ci ripenso, penso che quella serata per me è stata un po’ magica. Ho tanti ricordi belli. Tipo te che balli felice, gli sguardi, il video che ti hanno fatto che mi ha fatto commuovere ahaha, te che ti butti su di me ahaha, vedere le tue amiche per la prima volta, anche se non mi sono nemmeno presentato ahaha. E vedere pure come ti prendevano in giro per come mangi 😌"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-3/original/27.jpg","thumbKey":"bacheca/settembre/giorno-3/thumb/27.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Quello è stato proprio il giorno delle corse ahaha, per prepararmi, per andare alla tua festa, per prendere la macchina. Ma anche il giorno del parrucchiere, mi ricordo che una volta mi avevi detto qualcosa che ti aveva colpita di me quel giorno, ma non ricordo cosa. Però ricordo che ti ho detto che fumavo, e ti ho dato il kinder bueno ahaha. La sera mi avevi chiesto se mi ero portato la sigaretta e ricordo che non lo avevo fatto proprio perché non volevo che la tua famiglia pensasse male ahaha"}]}]}]}', 2, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 4, 'settembre', 'il-quarto-giorno', 'Il quarto giorno', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/01.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/01.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/02.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/02.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/03.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/03.jpg","caption":"Non so perché anche se ti vedi appena, mi piaceva un sacco guardare questa foto, hai quello sguardo che sembrava proprio innamorato"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/04.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/04.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/05.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/05.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/06.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/06.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/07.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/07.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/08.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/08.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/09.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/09.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/10.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/10.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-4/original/11.jpg","thumbKey":"bacheca/settembre/giorno-4/thumb/11.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Beh che dire, anche di questa giornata non abbiamo molte foto, ma sono contento che abbiamo almeno queste, perché boh per me sono tra le più belle. Mi piace guardare che occhioni che avevi, erano enormi anche se avevi la luce puntata in faccia ahaha. Amo le ultime due, ovviamente mi piacciono anche quelle prima, però boh, le ultime due, hanno qualcosa, quell’abbraccio, il bacio sulla fronte. Beh ovviamente le nostre cheesecake ahaha quella giornata la ricordiamo bene, anche se non si vede quella maglietta era già sporca. Quella sera ti ho dato quel bracciale, abbiamo giocato a monopoly per la prima volta e avevi quel vestito che sai quanto mi piaceva vedertelo addosso. Secondo me in queste 8 foto è racchiuso tanto amore"}]}]}]}', 3, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 5, 'settembre', 'il-quinto-giorno', 'Il quinto giorno', '{"rows":[{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/01.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/01.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/02.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/02.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/03.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/03.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/04.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/04.jpg","caption":"Mi ricordo che quel giorno avevo voglia di farti foto a caso, eri bella. E poi volevo darti un po’ di fastidio forse ahaha guarda quanto mi stavi odiando"}]},{"width":0.5000000000000001,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/05.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/05.jpg","caption":"Di quelle giornate mi ricordo tanto il fatto che non avevamo mai fame e volevamo semplicemente stare insieme, anche senza mangiare ahaha. Però un po’ mi sentivo in colpa che non ti facessi mangiare e quindi qui ero contento perché avevi fame e ti avevo comprato tutto quello che volevi ahaha. Mi ricordo che avevo preso il kebab ed è caduto tutto l’olio e mi ricordo che questa cosa ci aveva fatto ridere. Poi vabbé le nuggest. E ti sblocco un ricordo, che si è appena sbloccato a me. Ti ricordi che ci conoscevano tipo TUTTI? Perché la sera prima mentre andavamo in bagno avevamo conosciuto tipo tutti quelli del B&B, e quel giorno abbiamo scoperto che erano praticamente tutti quelli che lavoravano lì ahaha. Però ci hanno tratto bene"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/06.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/06.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-5/original/07.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/07.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-5/original/08.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/08.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/09.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/09.jpg","caption":"30 euro di caramelle 👀. Però in questa foto si vedono sia le giuggiole che gli ovetti. E se ci fai caso anche un cuoricino"}]}]},{"columns":[{"width":1,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/10.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/10.jpg","caption":"Io mi ricordo perché ridevi. Ahaha eri stronza e io ti baciavo e tu stavi ferma e io mi lamentavo e a te veniva da ridere. Però è venuta una bella foto lo ammetto"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/11.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/11.jpg"}]},{"width":0.5000000000000002,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/12.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/12.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-5/original/13.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/13.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-5/original/14.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/14.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/15.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/15.jpg"}]},{"width":0.5000000000000001,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/16.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/16.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/17.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/17.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/18.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/18.jpg","caption":"Non sai quanto mi manca a volte vedere quel faccino"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Tutte queste foto mi piacciono perché tante sono stupide ahaha e boh mi fanno ridere, era bella perché stavamo “giocando” a farci le foto, era bello. E poi vabbé c’è quella faccia che hai fatto che è alla fine è diventata uno sticker ahaha. Comunque guarda le ultime quattro in sequenza, fanno riderissimo ahaha, chissà che ti avevo detto"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/19.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/19.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/20.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/20.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/21.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/21.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/22.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/22.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/23.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/23.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-5/original/24.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/24.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-5/original/25.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/25.jpg","caption":"Il nostro sfondo"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/26.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/26.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/27.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/27.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Queste due foto sono belle, eravamo super abbracciati. Ma ti giuro che non capisco com’eravamo messi, come avevamo le mani? Ahaha c’è una mia mano dietro di me e una tua mano che spunta da giù. Non lo so, mi confondono ahaha"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/28.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/28.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-5/original/29.jpg","thumbKey":"bacheca/settembre/giorno-5/thumb/29.jpg","caption":"Lo sai, questa è una delle mie preferite, perché tu ridi, lo so, non ti stai ammazzando dalle risate ahaha, ma quel sorriso mi piace"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Quello è un giorno speciale secondo me, forse perché era il primo giorno intero che passavamo insieme dalla mattina alla sera. Ricordo il giro che ci siamo fatti alla fiera, abbiamo guardato tipo tutto quello che si poteva. Ci siamo girati tutti gli stand delle caramelle per trovare quello perfetto in cui comprarle ahaha e alla fine siamo tornati tipo al secondo. Beh poi ricordo come sei scoppiata a ridere quando ti ho detto il prezzo delle caramelle ahaha e che mi hai detto che eri scappata più lontano per fare finta di non sentire ahaha. Però io te ne avrei comprate pure di più. Alla fine chi se ne se frega? I soldi si spendono per le persone che ami. Poi appunto il pranzo fuori e non so che abbiamo fatto il pomeriggio sinceramente ahaha. Ricordo che poi siamo andati in stanza, quel giorno ti ho letto quella letterina che ti ha fatta piangere, spero perché fosse bella ahaha. Poi abbiamo mangiato finalmente le patatine che tipo aspettavano lì dal giorno 1 mentre guardavamo quella piccolissima tv, ricordo che ti avevo comprato l’acqua frizzante, ma era troppo frizzante ahaha poi quel giorno abbiamo ascoltato la playlist dicevi che ti piaceva tanto. Ricordo che in quei giorni volevi sempre ascoltare un po’ di musica con me. E poi vabbé la sera non abbiamo nemmeno cenato, tra le patatine e le caramelle eravamo pieni ahaha, poi siamo andati a prendere il pigiama da te e alla fine abbiamo dormito insieme abbracciati. Quindi direi che tutto sommato è stata una bella giornata"}]}]}]}', 4, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 6, 'settembre', 'l-ultimo-giorno', 'L’ultimo giorno', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/01.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/01.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-6/original/02.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/02.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-6/original/03.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/03.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"L’ultima di queste 3 foto secondo te è venuta benissimo. Ceh è proprio stupenda. Sarebbe una di quelle foto perfette da usare come sfondo del telefono. Ti posso dire anche che avevi delle unghie bellissime? Ahaha comunque qui ci eravamo svegliati da poco più o meno, e mi ricordo che mentre stavamo preparando le cose per lasciare la camera mi sono ricordato che avevo pensato di comprare apposta quei due cuori per mangiarli insieme. Non avevo pensato che sarebbero uscite pure delle foto belle ahaha. O forse almeno a queste ci avevo pensato? Onestamente non ricordo bene ahaha. Comunque vuoi sapere una cosa carina per cui adesso mi sento un po’ uno stupido? Mi ricordo che in quei giorni io volevo fare tante altre cose, non mi ricordo cosa, però pensavo sempre “faccio questo! ..No dai è troppo”. Avevo sempre paura che tutto quello che potessi fare per te era “troppo”, come se in qualche modo stessi forzando la mano nel fare succedere delle cose romantiche a tutti i costi no?"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Me lo sono ricordato perché questa cosa delle caramelle a forma di cuore era una di quelle. Infatti ne ho prese solo 2, per qualche motivo non volevo che pensassi che facevo delle cose solo per farti vedere che sono dolce ahaha. E quindi anche qui “le caramelle a forma di cuore ok, ma solo 2 giusto per il simbolo”. Non lo so, non volevo “esagerare”. Come se darti troppo amore o fare troppe cose belle potesse sembrare “troppo”. Però tante cose avrei voluto farle. Un po’ come la cosa di ballare se ci pensi no? Entrambi eravamo tipo “ma no dai che cavolata 😅”. Però in realtà avremmo voluto tutti e due"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/04.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/04.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/05.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/05.jpg","caption":"Quel giorno ti avrei comprato pure tutto il bar ahaha ero troppo triste che stava per finire tutto"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/06.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/06.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/07.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/07.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/08.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/08.jpg"}]}]},{"columns":[{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/09.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/09.jpg"}]},{"width":0.33333333333333337,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/10.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/10.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/11.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/11.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/12.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/12.jpg","caption":"Chi lo avrebbe detto che quel gesto piccolo, poi sarebbe diventato così importante?"}]},{"width":0.5000000000000001,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/13.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/13.jpg"},{"type":"photo","key":"bacheca/settembre/giorno-6/original/14.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/14.jpg","caption":"Questa foto è troppo tenera ahaha"},{"type":"photo","key":"bacheca/settembre/giorno-6/original/15.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/15.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/16.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/16.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/giorno-6/original/17.jpg","thumbKey":"bacheca/settembre/giorno-6/thumb/17.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"video","key":"bacheca/settembre/giorno-6/web/altalena-1.mp4"}]},{"width":0.5,"blocks":[{"type":"video","key":"bacheca/settembre/giorno-6/web/altalena-2.mp4"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Vederti lì sull’altalena in video, con le cose che ci diciamo, mi ha sempre fatto uno strano effetto sai? Questo video ha davvero il sapore di quei video musicali, di quei ricordi che sono tipo tutti in sequenza no? Sembra uno di quei momenti stra belli e felici, che ora appunto sono nostalgici. Non so come spiegarlo ahaha. Però mi è sempre piaciuto avere questi due video, e mi sento stupido, perché abbiamo solo questi due, e oltre la mia voce, io nemmeno ci sono ahaha"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"E con questi 2 video si chiude il nostro ultimo giorno e i nostri ultimi ricordi insieme. Ricordo che quel giorno ero tanto triste, ma non sapevo ancora quanto sarei stato triste nei giorni subito dopo ahaha. Ricordo che mi mancavi da morire e che ancora era tutto vivo nella mia mente. Avrei dovuto scrivere di più, in modo che un giorno avrei potuto ricordare ogni singolo attimo alla perfezione. Qualcosa sono sicuro di averla scritta, ma sai, non è lì tipo “racconto” no? Ahaha peccato. Ricordo come nelle settimane successive continuavo a mettere il tuo elastico sotto il naso, per sentire ancora il tuo odore e il tuo profumo, perché si riuscivo a distinguerli ahaha. Facevo i salti mortali per non bagnarlo o “sporcarlo” con altri odori. Fino a che pian piano quello che sentivo è diventato solo una puntina lontana e alla fine non lo sentivo più. Ricordare un odore è difficile purtroppo. In ogni caso comunque è stato bello rivivere un po’ quei ricordi, inizialmente ha fatto male, ma man mano che li vedevo, sorridevo sempre di più. E mi rendo conto, anche se lo sapevo già che ogni attimo di quei giorni per me è stato unico, spero che sia stato bello anche per te riviverli con me"}]}]}]}', 5, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 7, 'settembre', 'due-fotine-bonus', 'Due fotine bonus', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/settembre/bonus/original/01.jpg","thumbKey":"bacheca/settembre/bonus/thumb/01.jpg","caption":"La maglietta sporca del tuo trucco"}]},{"width":0.5000000000000001,"blocks":[{"type":"photo","key":"bacheca/settembre/bonus/original/02.jpg","thumbKey":"bacheca/settembre/bonus/thumb/02.jpg","caption":"Lo scontrino del nostro primo appuntamento che porto ancora nel mio portafogli"}]}]}]}', 6, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_periods (id, title, position, created_by, created_at, updated_at)
SELECT 'maggio', 'Maggio', 1, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
