INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 8, 'maggio', 'il-primo-giorno', 'Il primo giorno', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/01.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/01.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"Inizia tutto di nuovo davanti a questo portone. Tu forse non puoi capire l’emozione di esserci davanti, perché tu giustamente ci vivi. Ma per me è stupendo ogni volta, racchiude un po’ quella magia. È come se sapessi che dietro quel portone si trova la felicità e tutto quello che voglio. E questo portone è così difficile da raggiungere che ogni volta che ci sono stato davanti, mi ha fatto battere il cuore. Per me è speciale, non perché è un posto che non avevo mai visto, anzi, l’ho visto molte volte, ma poterlo vedere con i miei occhi è qualcosa di unico ogni singola volta"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/02.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/02.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/03.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/03.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Beh in qualche modo queste due foto sono speciali forse no? Abbiamo potuto vedere davvero il nostro filo rosso. Quella lettere che ti avevo scritto con il disegno mi piaceva così tanto che volevo renderla ancora più speciale con questo momento qui. E ora sono quali incredulo che sia diventato realtà. Spero che queste foto e questo filo, siano un augurio. E spero che davvero, per quanto sia tutto complicato, io e te abbiamo conosciuto il nostro filo rosso"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/04.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/04.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"Sono contento che ci sia questa foto, la nostra prima cosa cucinata insieme"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/05.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/05.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/06.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/06.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/07.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/07.jpg"},{"type":"text","text":"Di questo momento ricordo due cose, io che sniffo continuamente il tuo profumo, e il battito del tuo cuore. Avevo la testa poggiata lì e lo sentivo perfettamente e non lo sentivo da troppo tempo, mi mancava. Ora grazie al tuo regalo, lo potrò portare sempre con me. Vorrei poter fare lo stesso con il tuo profumo"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-1/original/08.jpg","thumbKey":"bacheca/maggio/giorno-1/thumb/08.jpg"}]}]}]}', 0, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 9, 'maggio', 'il-secondo-giorno', 'Il secondo giorno', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-2/original/01.jpg","thumbKey":"bacheca/maggio/giorno-2/thumb/01.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"Non so perché ma questa foto mi piace, sei bella. E il nostro secondo giorno inizia così, con un piatto di pasta al pesto davanti, che nessuno dei due ama, ma che entrambi non mangiavamo da tanto ahaha"}]}]},{"columns":[{"width":1,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-2/original/02.jpg","thumbKey":"bacheca/maggio/giorno-2/thumb/02.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Comunque ti devo dire, hai fatto una foto stupenda, ceh mi piace proprio com’è venuta la luce e tutto. Mi dispiace che quelle candeline non potessero essere accese, sarebbe stato ancora più carino. Però sono felice che ti abbiamo fatto ridere così tanto che mi sono accorto dopo del rilevatore di fumo ahaha. Spero che questa sorpresa ti sia piaciuta tanto, pensavo da tanto a una cosa del genere e non volevo andare via senza essere riuscito a farla. Prima avevo pensato a una cosa diversa, da fare in un altro momento a gennaio. Ma mi sono dovuto adattare, spero che sia stato un bell’adattamento"}]}]},{"columns":[{"width":1,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-2/original/03.jpg","thumbKey":"bacheca/maggio/giorno-2/thumb/03.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-2/original/04.jpg","thumbKey":"bacheca/maggio/giorno-2/thumb/04.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-2/original/05.jpg","thumbKey":"bacheca/maggio/giorno-2/thumb/05.jpg"}]}]},{"columns":[{"width":1,"blocks":[{"type":"text","text":"Ed eccoti qua, una bellissima sirena, con suo regalo ahaha. Sono felice di avere queste foto, e devo dire che in particolare questa mi piace tanto, perché sembri davvero felice. Comunque devo dire che anche se purtroppo non ho il video, sono fiero della faccia che hai fatto. Hai aperto la bocca a hai iniziato a sorridere, parlavi, non so se lo facevi per smascherare o meno, però non riuscivi a smettere di sorridere ahaha e sinceramente era esattamente quello che speravo di ottenere, volevo che fossi felice e che avessi anche tu il tuo momento magico e perfetto. Mi dispiace che le kinder cards non ti piacciono. Pensavo di si. Uffa"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-2/original/06.jpg","thumbKey":"bacheca/maggio/giorno-2/thumb/06.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"È stato bello vedere il film insieme, sapeva di quella cosa che abbiamo aspettato per tanto tanto, troppo tempo e che alla fine finalmente è arrivata. Siamo stati abbracciati, ci siamo dati la mano, ed è stato bello. È stato bello commentarlo insieme, ridere per le cose stupide insieme e stringerti e darti un bacio sui capelli quando saltavi in aria ahaha. Dopo il film ci siamo abbracciati, forse anche qualcosa di più, e siamo rimasti così per boh? Tipo 1 ora? Non lo so onestamente, ho perso il senso del tempo. Ma è stato bello sentirti di nuovo così vicina"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"text","text":"Purtroppo il secondo giorno finisce così, però devo ammettere che dopo c’è comunque stato qualcosa di bello no? Lo so, forse non si può definire “bello” un momento in cui si piange, però alla fine quando c’è una conferma, una rivelazione, o anche solo un bel discorso fatto con le lacrime agli occhi, sai che in quel momento viene dal cuore, che ci sono meno filtri, meno muri o armature no? E comunque sono quelle cose che ti fanno sorridere"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-2/original/07.jpg","thumbKey":"bacheca/maggio/giorno-2/thumb/07.jpg"}]}]}]}', 1, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 10, 'maggio', 'il-terzo-giorno', 'Il terzo giorno', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/01.jpg","thumbKey":"bacheca/maggio/giorno-3/thumb/01.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"Non pensare male ahaha ho fatto la foto alle tue chiavi perché sono bellissime, mi piacciono un sacco i colori, è super armonioso. Mi piace che sia tutto argento bianco e questo rosa confetto bellissimo. Mi piace pensare che tu curi tantissimo anche questi piccoli particolari. E amo tanto questa cosa di te"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"text","text":"Questa invece serve a ricordaci un giorno che la stanza 7 è bellissima, se mai dovesse servirci, chiederò proprio quella ahaha"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/02.jpg","thumbKey":"bacheca/maggio/giorno-3/thumb/02.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/03.jpg","thumbKey":"bacheca/maggio/giorno-3/thumb/03.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"E queste beh, mi piaceva l’idea di vedere le nostre chiavi di casa insieme, vicine. Mentre scrivevo guardando questa foto mi sono reso conto di una cosa GIURO che non l’ho fatto apposta ahaha. Le nostre chiavi vicine sembra che fanno il numero “17”. Le tue messe unite, sembra che siano l’1, mentre vabbé le mie hanno proprio un 7 enorme ahaha. Che cosa bellissima"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/018-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/019-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/020-photo.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/021-photo.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/022-photo.jpg"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/023-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/024-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/025-photo.jpg"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/026-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/027-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/028-photo.jpg"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/029-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/030-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/031-photo.jpg"}]}]},{"columns":[{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/032-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/033-photo.jpg"}]},{"width":0.3333333333333333,"blocks":[{"type":"video","key":"bacheca/maggio/giorno-3/web/001-video.mp4"}]}]},{"columns":[{"width":1,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/034-photo.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/035-photo.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/giorno-3/original/036-photo.jpg"}]}]}]}', 2, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
