INSERT INTO bacheca_days (id, period_id, slug, title, content, position, created_by, created_at, updated_at)
SELECT 11, 'maggio', 'screenshots', 'Screenshots', '{"rows":[{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/01.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/01.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/02.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/02.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/03.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/03.jpg"},{"type":"text","text":"Beh che dire? Si è bello essere così vicini, ma non ci voleva un genio per dirlo no? Amo davvero il fatto che mi dici “vieni” e in 2 secondi sono da te. Vorrei che potesse essere così per sempre. Vorrei che vivessimo nella stessa città, non per vederci tutti i giorni, ma quanto meno per vederci più facilmente, anche fosse una volta al mese. Però non so. Qualcosa mi dice che se fossimo nella stessa città staremmo già vivendo insieme da un pezzo ahaha"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/04.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/04.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"text","text":"Ho messo quel messaggio che volevi nel documento, metto qui il link. Messaggio.Ma anche io volevo salvare la tua risposta, perché comunque è bella, ci sono cose importanti, e si anche se potrei prenderla in qualsiasi momento da ig, così sarà più facile recuperarla","link":{"href":"https://docs.google.com/document/d/10hqyWqgTlwno_3-9z2qafS1zLgWAsaAAYwNOpOaOzvY/edit?tab=t.0#heading=h.3qqgeqjm35uu","label":"Messaggio"}}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/05.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/05.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/06.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/06.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/07.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/07.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/08.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/08.jpg"}]},{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/09.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/09.jpg"}]}]},{"columns":[{"width":0.5,"blocks":[{"type":"photo","key":"bacheca/maggio/screenshots/original/10.jpg","thumbKey":"bacheca/maggio/screenshots/thumb/10.jpg"}]},{"width":0.5,"blocks":[{"type":"text","text":"Vorrei che potesse essere tutto come ci dici tu. Magari un giorno a Roma ci andremo. Comunque si, io lo sento che non è la fine, anche se non lo posso sapere, io non sento che è la fine. Sento solo che come sempre è il momento sbagliato. E spero che sarà come dice l’immagine che mi hai condiviso, dici che alla fine siamo sempre noi, lo so. Siamo noi. Vorrei poterlo essere sempre fino in fondo. Vorrei vedere i tuoi outfit tutti giorni, anche se non stiamo insieme, vorrei poterti baciare anche se non stiamo insieme, stringerti anche se non stiamo insieme, vorrei tutto, pure se non stiamo insieme. Perché siamo noi. E perché se alla fine siamo sempre io e te, allora che senso ha aspettare?"}]}]}]}', 3, u.id, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP
FROM users u WHERE u.email = 'rory982011@gmail.com';

